package server

import (
	"net/http"
	"os"
	"strconv"
)

func maxBodyBytes() int64 {
	limit, err := strconv.ParseInt(os.Getenv("MAX_BODY_BYTES"), 10, 64)
	if err != nil {
		return 1 << 20
	}
	return limit
}

func limitBody(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes())
}
